#include "codegen.hpp"
#include <sstream>
#include <unordered_map>
namespace minic { namespace {
std::string regFor(const std::string& name,std::unordered_map<std::string,std::string>& regs,int& next){auto it=regs.find(name);if(it!=regs.end())return it->second;auto r="%r"+std::to_string(++next);regs[name]=r;return r;}
}
std::string generateAssembly(const std::vector<IRInstruction>& ir){std::ostringstream o;std::unordered_map<std::string,std::string> regs;int next=0;for(const auto& i:ir){switch(i.op){case IROp::LoadConst:o<<"MOV "<<regFor(i.dest,regs,next)<<", "<<i.value<<'\n';break;case IROp::LoadVar:o<<"LOAD "<<regFor(i.dest,regs,next)<<", ["<<i.left<<"]\n";break;case IROp::Add:o<<"ADD "<<regFor(i.dest,regs,next)<<", "<<regFor(i.left,regs,next)<<", "<<regFor(i.right,regs,next)<<'\n';break;case IROp::Sub:o<<"SUB "<<regFor(i.dest,regs,next)<<", "<<regFor(i.left,regs,next)<<", "<<regFor(i.right,regs,next)<<'\n';break;case IROp::Mul:o<<"MUL "<<regFor(i.dest,regs,next)<<", "<<regFor(i.left,regs,next)<<", "<<regFor(i.right,regs,next)<<'\n';break;case IROp::Div:o<<"DIV "<<regFor(i.dest,regs,next)<<", "<<regFor(i.left,regs,next)<<", "<<regFor(i.right,regs,next)<<'\n';break;case IROp::Neg:o<<"NEG "<<regFor(i.dest,regs,next)<<", "<<regFor(i.left,regs,next)<<'\n';break;case IROp::Store:o<<"STORE ["<<i.dest<<"], "<<regFor(i.left,regs,next)<<'\n';break;}}return o.str();}
std::string generatePtxPreview(const std::vector<IRInstruction>& ir){std::ostringstream o;o<<"// PTX preview only: inspect and validate with NVIDIA tools before use.\n.version 7.0\n.target sm_70\n.address_size 64\n\n.visible .entry minicompiler_kernel() {\n";std::unordered_map<std::string,std::string> regs;int next=0;for(const auto& i:ir){switch(i.op){case IROp::LoadConst:o<<"    // "<<i.dest<<" = "<<i.value<<" (constant materialization omitted)\n";break;case IROp::LoadVar:o<<"    // load variable '"<<i.left<<"' requires an explicit memory layout\n";break;case IROp::Add:o<<"    add.s64 "<<regFor(i.dest,regs,next)<<", "<<regFor(i.left,regs,next)<<", "<<regFor(i.right,regs,next)<<";\n";break;case IROp::Sub:o<<"    sub.s64 "<<regFor(i.dest,regs,next)<<", "<<regFor(i.left,regs,next)<<", "<<regFor(i.right,regs,next)<<";\n";break;case IROp::Mul:o<<"    mul.lo.s64 "<<regFor(i.dest,regs,next)<<", "<<regFor(i.left,regs,next)<<", "<<regFor(i.right,regs,next)<<";\n";break;case IROp::Div:o<<"    // signed division requires a defined lowering sequence\n";break;case IROp::Neg:o<<"    neg.s64 "<<regFor(i.dest,regs,next)<<", "<<regFor(i.left,regs,next)<<";\n";break;case IROp::Store:o<<"    // store result to variable '"<<i.dest<<"' requires an explicit memory layout\n";break;}}o<<"    ret;\n}\n";return o.str();}
}
